// security-contact: atlas@cryptolink.tech
pragma solidity =0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract Security is Ownable, Pausable, ReentrancyGuard {
    uint private constant WATCHER_NEVER_EXPIRE = 999999999999999999;

    mapping(address => uint) public WATCHER_STATUS;
    address[] public WATCHERS;
    uint public PAUSED_UNTIL;
    bool public INIT;

    event AddWatcher(address watcher);
    event RemoveWatcher(address watcher);
    event SecurityPause(address watcher, uint pausedUntil);
    event SecurityUnpause();

    modifier initOnce {
        require(INIT == false, "Security: contract already initalized");
        INIT = true;
        _;
    }

    modifier onlySecurityWatcher {
        require(WATCHER_STATUS[msg.sender] > block.timestamp, "Security: address not watcher");
        _;
    }

    function securityPause() external onlySecurityWatcher {
        PAUSED_UNTIL = block.timestamp + (60 minutes);
        _pause();
        emit SecurityPause(msg.sender, PAUSED_UNTIL);
    }

    function securityUnpause() external onlyOwner {
        require(PAUSED_UNTIL < block.timestamp, "Security: pause timer still activated");
        _unpause();
        emit SecurityUnpause();
    }

    function addWatcher(address _watcher) external onlyOwner {
        // first time we seen this watcher, add to watcher log
        if(WATCHER_STATUS[_watcher] == 0) {
            WATCHERS.push(_watcher);
        }

        WATCHER_STATUS[_watcher] = WATCHER_NEVER_EXPIRE;

        emit AddWatcher(_watcher);
    }

    function removeWatcher(address _watcher) external onlyOwner {
        require(WATCHER_STATUS[_watcher] > 0, "Security: address not watcher");

        WATCHER_STATUS[_watcher] = block.timestamp + (1 days);

        emit RemoveWatcher(_watcher);
    }
}"
    },
    "contracts/MessageV3.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
// (c)2021-2024 Atlas - All Rights Reserved
// security-contact: atlas@cryptolink.tech
pragma solidity =0.8.17;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "./includes/Security.sol";

interface IClient {
    function messageProcess(uint txId, uint sourceChainId, address sender, address recipient, uint, bytes calldata data) external;
}

interface IPOSLayer {
    function validate(uint txId, uint sourceChainId, uint destChainId, address sender, address recipient, bytes[] calldata data) external returns (bool);
}

interface IWETH {
    function deposit() external payable;
    function transfer(address to, uint value) external returns (bool);
    function approve(address spender, uint amount) external returns (bool);
    function withdraw(uint amount) external;
    function balanceOf(address account) external view returns (uint);
}

contract MessageV3 is Security {
    mapping(uint => bool) public processedTransfers;
    mapping(uint => bool) public failedTransfers;
    mapping(uint => bool) public enabledChains;
    mapping(uint => uint) public expressFee;
    mapping(address => bool) public whitelist;
    mapping(address => bool) public bridgeATeam;
    mapping(address => bool) public bridgeOperators;
    mapping(address => bool) public bridgeSupers;
    mapping(address => uint) public customSourceFee;
    mapping(address => uint) public maxgas;
    mapping(address => uint) public maxfee;
    mapping(address => address) public exsig;

    address public poslayer;
    address public chainsig;
    address public accountant;
    address public weth;
    address public paper; // for backwards compat
    address public feeToken;
    uint public feeTokenDecimals;
    uint public chain;
    uint public nextTxId;
    uint public minFee;
    bool public bridgeEnabled;
    bool public takeFeesOffline;
    bool public whitelistOnly;
    bool public unwrapWETH;

    modifier onlyOperator {
        require(bridgeOperators[msg.sender] == true, "MessageV3: caller is not an operator");
        _;
    }

    modifier onlySuper {
        require(bridgeSupers[msg.sender] == true, "MessageV3: caller is not a super");
        _;
    }

    modifier onlyATeam {
        require(bridgeATeam[msg.sender] == true, "MessageV3: caller is not an ateam");
        _;
    }

    event SendRequested(uint txId, address sender, address recipient, uint chain, bool express, bytes data, uint16 confirmations);
    event SendProcessed(uint txId, uint sourceChainId, address sender, address recipient);
    event Success(uint txId, uint sourceChainId, address sender, address recipient, uint amount);
    event SetChainsig(address signer);
    event SetPOSLayer(address poslayer);
    event SetExsig(address caller, address signer);
    event SetMaxgas(address caller, uint maxGas);
    event SetMaxfee(address caller, uint maxFee);
    event SetOperator(address account, bool status);
    event SetSuper(address account, bool status);
    event SetATeam(address account, bool status);
    event SetAccountant(address accountant);
    event SetBridgeStatus(bool status);
    event SetTakeFeesOffline(bool status);
    event SetChainStatus(uint chain, bool status, uint minToken, uint expressFee);
    event SetFeeToken(address feeToken, uint feeTokenDecimals);
    event SetWeth(address weth);
    event SetUnwrapWETH(bool enabled);
    event SetCustomSourceFee(address wallet, uint amount);
    event SetMinFee(uint minFee);
    event SetWhitelistOnly(bool status);
    event SetWhitelist(address wallet, bool status);
    event Recover(address token, uint amount);
    event ErrorLog(uint txId, string message);

    constructor(uint _chain) {
        chain    = _chain;
        nextTxId = _chain * 10**23;
    }

    function init(address _weth, address _feeToken, address _accountant) external onlyOwner initOnce {
        accountant = _accountant;
        weth       = _weth;
        feeToken   = _feeToken;
        paper      = _feeToken;
        unwrapWETH = true; // default state for most chains

        // @note Crucially needed since we use withdraw() later on
        if (_weth != address(0)) IWETH(weth).approve(weth, type(uint).max);

        if(_feeToken != address(0)) {
            feeTokenDecimals = IERC20Metadata(_feeToken).decimals();
            // @note This will need to be > than our desired decimal precision
            require(feeTokenDecimals >= 6, "Fee token has too few decimals");
        }

        minFee = 250000;  // 0.25
    }

    /** USER FUNCTIONS */
    // @dev for backwards compatibility with general bridge
    function sendRequest(address _recipient, uint _chain, uint, address, bytes calldata _data, uint16 _confirmations) external returns (uint _txId) {
        return _send(_recipient, _chain, _data, _confirmations, false);
    }

    // @dev for backwards compatibility with general bridge
    function sendRequestExpress(address _recipient, uint _chain, uint, address, bytes calldata _data, uint16 _confirmations) external returns (uint _txId) {
        return _send(_recipient, _chain, _data, _confirmations, true);
    }

    function sendMessage(address _recipient, uint _chain, bytes calldata _data, uint16 _confirmations, bool _express) external returns (uint _txId) {
        return _send(_recipient, _chain, _data, _confirmations, _express);
    }        

    // @dev we want to be able to "reenter" so contracts may send replies or multiple additional outgoing messages
    function _send(address _recipient, uint _chain, bytes calldata _data, uint16 _confirmations, bool _express) internal whenNotPaused returns (uint _txId) {
        require(bridgeEnabled == true, "MessageV3: contract not enabled");

        // if whitelist
        if(whitelistOnly == true) {
            require(whitelist[msg.sender] == true, "MessageV3: not on whitelist");
        }

        // make sure the destination chain is activated
        require(enabledChains[_chain] == true, "MessageV3: destination chain is not enabled");

        // do not send to the zero address
        require(_recipient != address(0), "MessageV3: cannot send to zero address");

        uint _fee = getSourceFee(_chain, _express);
        if(_fee > 0) {
            if(maxfee[msg.sender] > 0) {
                require(_fee <= maxfee[msg.sender], "MessageV3: fee over max set by client");
            }
            SafeERC20.safeTransferFrom(IERC20(feeToken), msg.sender, accountant, _fee);
        }

        // generate next unique tx id
        _txId = getNextTxId();

        // generate chain event
        emit SendRequested(_txId, msg.sender, _recipient, _chain, _express, _data, _confirmations);
    }

    // @dev implementing contract controlls this (msg.sender)
    function setExsig(address _signer) external {
        exsig[msg.sender] = _signer;
        emit SetExsig(msg.sender, _signer);
    }

    // @dev implementing contract controlls this (msg.sender)
    function setMaxgas(uint _maxGas) external {
        maxgas[msg.sender] = _maxGas;
        emit SetMaxgas(msg.sender, _maxGas);
    }

    // @dev implementing contract controlls this (msg.sender)
    function setMaxfee(uint _maxFee) external {
        maxfee[msg.sender] = _maxFee;
        emit SetMaxfee(msg.sender, _maxFee);
    }
    /** END USER FUNCTIONS */

    /** OPERATOR FUNCTIONS */
    // @dev _data[0] = user payload, _data[1] = exsig, _data[2] = chainsig, _data[3+] = poslayer
    function process(uint _txId, uint _sourceChainId, uint _destChainId, address _sender, address _recipient, uint _gas, bytes[] calldata _data) external onlyOperator nonReentrant whenNotPaused {
        require(bridgeEnabled == true, "MessageV3: contract not enabled");

        // make sure this message is for this destination chain
        require(_destChainId == chain, "MessageV3: dest chain mismatch");

        // do not process duplicate transactions
        require(processedTransfers[_txId] != true, "MessageV3: transaction already processed");

        // check/enforce maxGas
        if(maxgas[_recipient] > 0) {
            require(_gas <= maxgas[_recipient], "MessageV3: gas over max set by client");
        }

        // check if we require external project signature
        if(exsig[_recipient] != address(0)) {
            (address _signerRecovered, ) = ECDSA.tryRecover(ECDSA.toEthSignedMessageHash(keccak256(abi.encode(
                _txId,
                _sourceChainId,
                _destChainId,
                _sender,
                _recipient,
                _data[0]
            ))), _data[1]);
            require(_signerRecovered == exsig[_recipient], "MessageV3: invalid external project signature");
        }

        // check if we require external chain signature
        if(chainsig != address(0)) {
            (address _signerRecovered, ) = ECDSA.tryRecover(ECDSA.toEthSignedMessageHash(keccak256(abi.encode(
                _txId,
                _sourceChainId,
                _destChainId,
                _sender,
                _recipient,
                _data[0]
            ))), _data[2]);
            require(_signerRecovered == chainsig, "MessageV3: invalid external chain signature");
        }

        // if we enabled proof of stake layer, call the module here
        if(poslayer != address(0)) {
            require(IPOSLayer(poslayer).validate(
                _txId,
                _sourceChainId,
                _destChainId,
                _sender,
                _recipient,
                _data                
            ), "MessageV3: could not validate pos layer");
        }

        // mark transaction as processed
        processedTransfers[_txId] = true;

        // send gas back to tx.origin
        if(_gas > 0) {
            IERC20 _weth = IERC20(weth);
            require(_weth.allowance(_recipient, address(this)) >= _gas, "MessageV3: recipient did not approve weth for gas");
            require(_weth.balanceOf(_recipient) >= _gas, "MessageV3: recipient does not have available weth for gas");

            SafeERC20.safeTransferFrom(_weth, _recipient, address(this), _gas);

            if(unwrapWETH) {
                IWETH(address(_weth)).withdraw(_weth.balanceOf(address(this)));
                address payable _originator = payable(tx.origin);
                (bool _sent, ) = _originator.call{ value: address(this).balance }("");
                require(_sent, "MessageV3: could not refund gas to caller");
            } else {
                SafeERC20.safeTransfer(_weth, tx.origin, _gas);
            }
        }

        try MessageV3(this).processCall(_txId, _sourceChainId, _sender, _recipient, _data[0]) returns (bool _success, string memory _reason) {
            if(_success) {
                emit Success(_txId, _sourceChainId, _sender, _recipient, 0);
            } else {
                failedTransfers[_txId] = true;
                emit ErrorLog(_txId, string.concat("MessageV3: recipient: ", _reason));
            }
        // @dev If for some reason the address fed to IClient is completely wrong and not even a contract, this "double-catch" will catch it here
        } catch { 
            failedTransfers[_txId] = true;
            emit ErrorLog(_txId, "MessageV3: uncallable: fatal failure");
        }

        emit SendProcessed(_txId, _sourceChainId, _sender, _recipient);
    }

    function processCall(uint _txId, uint _sourceChainId, address _sender, address _recipient, bytes calldata _data) external returns (bool, string memory _reason) {
        if(msg.sender != address(this)) return (false, "not self");

        // @dev this is backwards compatible with the general bridge, so passes 0 for the "amount"
        try IClient(_recipient).messageProcess(_txId, _sourceChainId, _sender, _recipient, 0, _data) {
            return (true, "");
        // @dev this is for regular revert() or require() inside of their contracts
        } catch Error(string memory reason) {
            return (false, reason);
        // @dev For extra safety to make sure some weird things contract might be throwing, like for example if their contract has the wrong method name or the ABI doesn't match. This will catch it
        } catch {
            return (false, "fatal failure");
        }
    }
    /** END OPERATOR FUNCTIONS */

    /** OWNER FUNCTIONS */
    function setOperator(address _account, bool _status) external onlyOwner {
        require(_account != address(0), "MessageV3: cannot set to zero address");
        bridgeOperators[_account] = _status;
        emit SetOperator(_account, _status);
    }

    function setSuper(address _account, bool _status) external onlyOwner {
        require(_account != address(0), "MessageV3: cannot set to zero address");
        bridgeSupers[_account] = _status;
        emit SetSuper(_account, _status);
    }

    function setChainsig(address _signer) external onlyOwner {
        chainsig = _signer;
        emit SetChainsig(_signer);
    }

    function setPOSLayer(address _poslayer) external onlyOwner {
        poslayer = _poslayer;
        emit SetPOSLayer(_poslayer);
    }
    /** END OWNER FUNCTIONS */

    /** SUPER FUNCTIONS */
    function superSetSuper(address _account, bool _status) external onlySuper {
        require(_account != address(0), "MessageV3: cannot set to zero address");
        bridgeSupers[_account] = _status;
        emit SetSuper(_account, _status);        
    }

    function setATeam(address _account, bool _status) external onlySuper {
        require(_account != address(0), "MessageV3: cannot set to zero address");
        bridgeATeam[_account] = _status;
        emit SetATeam(_account, _status);
    }

    function setChainStatus(uint[] calldata _chain, bool[] calldata _status, uint[] calldata _expressFee) external onlySuper {
        for(uint x; x < _chain.length; x++) {
            enabledChains[_chain[x]] = _status[x];
            expressFee[_chain[x]] = _expressFee[x];
            emit SetChainStatus(_chain[x], _status[x], 0, _expressFee[x]);
        }
    }

    function setAccountant(address _accountant) external onlySuper {
        accountant = _accountant;
        emit SetAccountant(accountant);   
    }

    function setFeeToken(address _feeToken) external onlySuper {
        feeToken = _feeToken;
        paper    = _feeToken;
        feeTokenDecimals = IERC20Metadata(_feeToken).decimals();
        // @note This will need to be > than our desired decimal precision
        require(feeTokenDecimals >= 6, "MessageV3: fee token has too few decimals");

        emit SetFeeToken(_feeToken, feeTokenDecimals);
    }

    function setWeth(address _weth) external onlySuper {
        weth = _weth;

        // @note Crucially needed since we use withdraw() later on
        if (_weth != address(0)) IWETH(weth).approve(weth, type(uint).max);

        emit SetWeth(_weth);
    }

    function setUnwrapWETH(bool _enabled) external onlySuper {
        unwrapWETH = _enabled;
        emit SetUnwrapWETH(_enabled);
    }

    function recover(address _token, uint _amount) external onlySuper {
        SafeERC20.safeTransfer(IERC20(_token), accountant, _amount);
        emit Recover(_token, _amount);
    }

    function setBridgeStatus(bool _status) external onlySuper {
        bridgeEnabled = _status;
        emit SetBridgeStatus(_status);
    }
    /** END SUPER FUNCTIONS */

    /** ATEAM ADMIN FUNCTIONS */
    function setTakeFeesOffline(bool _status) external onlyATeam {
        takeFeesOffline = _status;
        emit SetTakeFeesOffline(_status);
    }

    function setMinFee(uint _minFee) external onlyATeam {
        minFee = _minFee;
        emit SetMinFee(_minFee);
    }

    function setCustomSourceFee(address _contract, uint _amount) external onlyATeam {
        customSourceFee[_contract] = _amount;
        emit SetCustomSourceFee(_contract, _amount);
    }

    function setWhitelistOnly(bool _status) external onlyATeam {
        whitelistOnly = _status;
        emit SetWhitelistOnly(_status);
    }

    function setWhitelist(address _wallet, bool _status) external onlyATeam {
        whitelist[_wallet] = _status;
        emit SetWhitelist(_wallet, _status);
    }
    /** END ATEAM ADMIN FUNCTIONS */

    /** PUBLIC VIEWS */
    function getSourceFee(uint _destChainId, bool _express) public view returns (uint _fee) {
        if(takeFeesOffline) return 0;

        if(_express && expressFee[_destChainId] > 0) {
            _fee = expressFee[_destChainId];
        } else {
            _fee = minFee;
            uint _customSourceFee = customSourceFee[msg.sender];
            if(_customSourceFee > 0) {
                if(_customSourceFee == 9999) return 0;
                _fee = _customSourceFee;
            }
        }

        // @note This will need to equal our desired decimal precision
        _fee = _fee * (10 ** (feeTokenDecimals - 6));
    }

    // @dev for backwards compat, bridgev2 npm package uses this to collect the "bridge fee"
    function minTokenForChain(uint _destChainId) external view returns (uint _minToken) {
        return getSourceFee(_destChainId, false);
    }
    /** END PUBLIC VIEWS */

    /** PRIVATE INTERNAL UTILITIES */
    function getNextTxId() private returns (uint txId) {
        ++nextTxId;
        return nextTxId;
    }
    /** END PRIVATE INTERNAL UTILITIES */

    // @dev required since we convert WETH to ETH for gas refund
    receive() external payable {}
}
"
    }
  },
  "settings": {
    "optimizer": {
      "enabled": true,
      "runs": 200
    },
    "outputSelection": {
      "*": {
        "*": [
          "evm.bytecode",
          "evm.deployedBytecode",
          "abi"
        ]
      }
    },
    "metadata": {
      "useLiteralContent": true
    }
  }
}}
